  1014→function normalizeSheetName(name) {
  1015→  let result = '';
  1016→  for (let i = 0; i < name.length; i++) {
  1017→    const ch = name[i];
  1018→    result += KANGXI_MAP[ch] || ch;
  1019→  }
  1020→  return result;
