  1022→// Build a lookup: given a sheets object, find sheet by normalized name
  1023→function findSheet(sheets, name) {
  1024→  if (sheets[name]) return sheets[name];
  1025→  const norm = normalizeSheetName(name);
  1026→  for (const key of Object.keys(sheets)) {
  1027→    if (normalizeSheetName(key) === norm) return sheets[key];
  1028→  }
  1029→  return null;
  1030→}
  1031→// Get the actual key name in sheets object
  1032→function findSheetKey(sheets, name) {
  1033→  if (sheets[name] !== undefined) return name;
  1034→  const norm = normalizeSheetName(name);
  1035→  for (const key of Object.keys(sheets)) {
  1036→    if (normalizeSheetName(key) === norm) return key;
  1037→  }
  1038→  return null;
  1039→}
