  1041→/* ====== Utility Functions ====== */
  1042→function isNumeric(v) {
  1043→  if (v == null) return false;
  1044→  if (typeof v === 'number') return isFinite(v);
  1045→  if (typeof v === 'string') { const n = parseFloat(v); return !isNaN(n) && isFinite(n); }
  1046→  return false;
  1047→}
  1048→function toFloat(v) {
  1049→  if (v == null) return null;
  1050→  if (typeof v === 'number') return isFinite(v) ? v : null;
  1051→  if (typeof v === 'string') {
  1052→    if (v === '' || v === 'nan' || v === 'inf' || v === '-inf') return null;
  1053→    const n = parseFloat(v);
  1054→    return isFinite(n) ? n : null;
  1055→  }
  1056→  return null;
  1057→}
  1058→function escHtml(s) {
  1059→  if (s == null) return '';
  1060→  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  1061→}
