  1063→/* ====== Normalized Set Matching ====== */
  1064→function setHasNorm(theSet, name) {
  1065→  if (theSet.has(name)) return true;
  1066→  const norm = normalizeSheetName(name);
  1067→  for (const item of theSet) {
  1068→    if (normalizeSheetName(item) === norm) return true;
  1069→  }
  1070→  return false;
  1071→}
