  1073→/* ====== Column Type Detection ====== */
  1074→function detectColumnTypes(data, sheetName) {
  1075→  if (!data || !data[0]) return {};
  1076→  const headers = data[0];
  1077→  const colTypes = {};
  1078→  for (let ci = 0; ci < headers.length; ci++) {
  1079→    const h = String(headers[ci] || '');
  1080→    if (setHasNorm(PCT_RAW_SHEETS, sheetName)) {
  1081→      if (/年化|收益率|波动率|占比/.test(h)) { colTypes[ci] = 'percent_raw'; continue; }
  1082→    }
  1083→    if (setHasNorm(PCT_DECIMAL_SHEETS, sheetName)) {
  1084→      if (/年化|收益率|波动率|占比/.test(h)) { colTypes[ci] = 'percent'; continue; }
  1085→    }
  1086→    if (/bp/i.test(h)) { colTypes[ci] = 'bps'; continue; }
  1087→    const isPctHeader = /年化|收益率|波动率|占比|比例/.test(h);
  1088→    const numVals = [];
  1089→    for (let ri = 1; ri < Math.min(data.length, 20); ri++) {
  1090→      if (ci < data[ri].length) {
  1091→        const v = toFloat(data[ri][ci]);
  1092→        if (v != null && v !== 0) numVals.push(Math.abs(v));
  1093→      }
  1094→    }
  1095→    if (isPctHeader) {
  1096→      if (numVals.length > 0) {
  1097→        const avg = numVals.reduce((a,b) => a+b, 0) / numVals.length;
  1098→        colTypes[ci] = avg > 0.5 ? 'percent_raw' : 'percent';
  1099→      } else { colTypes[ci] = 'percent'; }
  1100→    } else if (numVals.length >= 2) {
  1101→      const avg = numVals.reduce((a,b) => a+b, 0) / numVals.length;
  1102→      const mx = Math.max(...numVals);
  1103→      if (avg > 0 && avg < 0.5 && mx < 1.5) colTypes[ci] = 'percent';
  1104→    }
  1105→  }
  1106→  return colTypes;
  1107→}
