  1109→/* ====== Cell Value Formatting ====== */
  1110→function formatCellValue(val, colType, useParens) {
  1111→  if (val == null) return '';
  1112→  if (typeof val === 'string') {
  1113→    if (val === 'nan' || val === 'inf' || val === '-inf') return '';
  1114→    const n = parseFloat(val);
  1115→    if (isFinite(n)) val = n; else return escHtml(val);
  1116→  }
  1117→  if (typeof val !== 'number' || !isFinite(val)) return '';
  1118→  if (colType === 'percent') return (val * 100).toFixed(2) + '%';
  1119→  if (colType === 'percent_raw') return val.toFixed(2) + '%';
  1120→  if (colType === 'bps') return val.toFixed(2);
  1121→  if (useParens) {
  1122→    if (Math.abs(val) < 0.05) return '-';
  1123→    if (Math.abs(val) < 1 && Math.abs(val) >= 0.05)
  1124→      return val < 0 ? '(' + Math.abs(val).toFixed(1) + ')' : val.toFixed(1);
  1125→    const r = Math.round(val);
  1126→    if (r === 0) return '-';
  1127→    if (r < 0) return '(' + Math.abs(r).toLocaleString() + ')';
  1128→    return r.toLocaleString();
  1129→  }
  1130→  if (Number.isInteger(val) || (val === Math.floor(val) && Math.abs(val) < 10000)) return String(Math.floor(val));
  1131→  if (Math.abs(val) < 0.0001 && val !== 0) return val.toFixed(6);
  1132→  if (Math.abs(val) < 0.01 && val !== 0) return val.toFixed(4);
  1133→  if (Math.abs(val) < 100) return val.toFixed(2);
  1134→  if (Math.abs(val) < 100000) return val.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
  1135→  return Math.round(val).toLocaleString();
  1136→}
