  1138→/* ====== Cell CSS Classes ====== */
  1139→function getCellClass(val, colType, header) {
  1140→  const fval = toFloat(val);
  1141→  if (fval == null) return '';
  1142→  const h = String(header).toLowerCase();
  1143→  const classes = [];
  1144→  const isChange = /变化|较上周|较上月|较上年|bp/.test(h);
  1145→  const isReturn = /年化|收益率/.test(h);
  1146→  if (isChange) { if (fval > 0) classes.push('val-positive'); else if (fval < 0) classes.push('val-negative'); }
  1147→  if (isReturn && colType === 'percent' && fval < 0) classes.push('val-negative');
  1148→  if (isChange && fval !== 0) {
  1149→    let intensity;
  1150→    if (colType === 'percent') intensity = Math.min(Math.abs(fval) * 20, 1);
  1151→    else if (colType === 'percent_raw') intensity = Math.min(Math.abs(fval) / 5, 1);
  1152→    else if (/bp/.test(h)) intensity = Math.min(Math.abs(fval) / 50, 1);
  1153→    else intensity = Math.min(Math.abs(fval) / 20, 1);
  1154→    const level = Math.min(Math.floor(intensity * 5) + 1, 5);
  1155→    classes.push(fval > 0 ? 'heat-pos-' + level : 'heat-neg-' + level);
  1156→  }
  1157→  return classes.join(' ');
  1158→}
