@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&family=Noto+Sans+SC:wght@300;400;500&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --bg:           #F2EFE9;
  --bg-card:      #FFFFFF;
  --bg-sidebar:   #FAFAF8;
  --bg-header:    #0C1F3D;
  --bg-th:        #0C1F3D;
  --bg-th2:       #1B3460;
  --bg-row-alt:   #F8F6F1;
  --bg-row-hover: #EEF3FB;
  --bg-total:     #E5E0D8;
  --bg-subtotal:  #EDE9E1;

  --text:         #1A1714;
  --text-sub:     #4A4540;
  --text-muted:   #7E7970;
  --text-th:      rgba(255,255,255,0.94);
  --text-th2:     rgba(255,255,255,0.78);

  --gold:         #A07820;
  --gold-light:   rgba(160,120,32,0.10);
  --navy:         #0C1F3D;
  --positive:     #145A2E;
  --negative:     #8B1A1A;

  --border:       #D5CFBF;
  --border-lt:    #E6E1D6;
  --border-th:    rgba(255,255,255,0.10);

  --sidebar-w:    210px;
  --hdr-h:        52px;

  --heat-pos-1: rgba(20,90,46,0.06); --heat-pos-2: rgba(20,90,46,0.12);
  --heat-pos-3: rgba(20,90,46,0.18); --heat-pos-4: rgba(20,90,46,0.26);
  --heat-pos-5: rgba(20,90,46,0.36);
  --heat-neg-1: rgba(139,26,26,0.06); --heat-neg-2: rgba(139,26,26,0.12);
  --heat-neg-3: rgba(139,26,26,0.18); --heat-neg-4: rgba(139,26,26,0.26);
  --heat-neg-5: rgba(139,26,26,0.36);
}

*{box-sizing:border-box;margin:0;padding:0;}
html{font-size:13px;scroll-behavior:smooth;}
body{font-family:'Noto Sans SC',-apple-system,'Microsoft YaHei',sans-serif;background:var(--bg);color:var(--text);line-height:1.5;overflow-x:hidden;}

/* ── Header ── */
.top-header{position:fixed;top:0;left:0;right:0;height:var(--hdr-h);background:var(--bg-header);border-bottom:2px solid var(--gold);display:flex;align-items:center;padding:0 18px;z-index:200;}
.header-brand{display:flex;align-items:center;gap:10px;}
.header-logo{width:28px;height:28px;background:var(--gold);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:13px;color:#fff;border-radius:2px;flex-shrink:0;}
.header-title{font-family:'Noto Serif SC',serif;font-size:15px;font-weight:600;color:rgba(255,255,255,0.95);letter-spacing:1.5px;white-space:nowrap;}
.header-date{font-size:11px;color:rgba(255,255,255,0.42);white-space:nowrap;}

.search-bar{margin-left:20px;}
.search-input{background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.14);border-radius:3px;color:rgba(255,255,255,0.82);font-size:12px;padding:5px 10px;width:170px;outline:none;font-family:inherit;}
.search-input::placeholder{color:rgba(255,255,255,0.30);}
.search-input:focus{border-color:var(--gold);background:rgba(255,255,255,0.11);}

.toolbar-btn{background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.16);border-radius:3px;color:rgba(255,255,255,0.75);font-size:11.5px;padding:5px 11px;cursor:pointer;display:flex;align-items:center;gap:5px;white-space:nowrap;transition:all 0.13s;font-family:inherit;}
.toolbar-btn:hover{background:rgba(255,255,255,0.14);color:#fff;}
.toolbar-btn svg{width:13px;height:13px;flex-shrink:0;}
.overview-upload-btn{border-color:rgba(160,120,32,0.45);color:rgba(210,170,80,0.90);}
.overview-upload-btn:hover{background:rgba(160,120,32,0.15);color:#E5BB50;}
.export-btn{border-color:rgba(255,255,255,0.22);}

/* ── Sidebar ── */
.sidebar{position:fixed;top:var(--hdr-h);left:0;bottom:0;width:var(--sidebar-w);background:var(--bg-sidebar);border-right:1px solid var(--border);overflow-y:auto;overflow-x:hidden;padding:10px 0;}
.sidebar::-webkit-scrollbar{width:3px;}
.sidebar::-webkit-scrollbar-thumb{background:var(--border);}
.sidebar-section{margin-bottom:2px;}
.sidebar-group-label{font-family:'Noto Serif SC',serif;font-size:9.5px;font-weight:600;color:var(--gold);letter-spacing:1.2px;padding:10px 12px 3px;border-top:1px solid var(--border-lt);text-transform:uppercase;}
.sidebar-section:first-child .sidebar-group-label{border-top:none;}
.nav-item{display:flex;align-items:center;gap:6px;padding:5px 12px;font-size:12px;color:var(--text-sub);text-decoration:none;border-left:2px solid transparent;transition:all 0.12s;}
.nav-item:hover,.nav-item.active{color:var(--navy);background:var(--gold-light);border-left-color:var(--gold);}
.nav-item.active{font-weight:500;}
.nav-icon{font-size:7px;color:var(--text-muted);}

/* ── Main ── */
.main-content{margin-left:var(--sidebar-w);margin-top:var(--hdr-h);padding:24px 26px 60px;}
.section{margin-bottom:36px;}
.section-header{font-family:'Noto Serif SC',serif;font-size:17px;font-weight:700;color:var(--navy);border-bottom:2px solid var(--navy);padding-bottom:7px;margin-bottom:18px;letter-spacing:0.3px;}
.sheet-title{font-family:'Noto Serif SC',serif;font-size:13px;font-weight:600;color:var(--gold);margin:18px 0 7px;padding-left:8px;border-left:3px solid var(--gold);}

/* ── Tables ── */
.table-wrapper{width:100%;overflow-x:auto;border:1px solid var(--border);border-radius:3px;margin-bottom:14px;background:var(--bg-card);}
.table-wrapper::-webkit-scrollbar{height:5px;}
.table-wrapper::-webkit-scrollbar-thumb{background:var(--border);border-radius:2px;}

table{width:100%;border-collapse:collapse;font-size:12px;}

th{background:var(--bg-th);color:var(--text-th);font-size:11px;font-weight:500;padding:7px 9px;text-align:center;white-space:nowrap;border-right:1px solid var(--border-th);border-bottom:1px solid var(--border-th);cursor:pointer;user-select:none;font-family:'Noto Sans SC',sans-serif;}
th:hover{background:#1B3460;}
th:last-child{border-right:none;}
.subheader-row th{background:var(--bg-th2);color:var(--text-th2);font-size:10.5px;}

td{padding:5px 9px;border-bottom:1px solid var(--border-lt);border-right:1px solid var(--border-lt);color:var(--text);vertical-align:middle;white-space:nowrap;max-width:200px;}
td:last-child{border-right:none;}
tr:nth-child(even):not(.header-row):not(.subheader-row):not(.total-row):not(.subtotal-row) td{background:var(--bg-row-alt);}
tr:hover:not(.header-row):not(.subheader-row) td{background:var(--bg-row-hover)!important;}

/* sticky first col for wide tables */
.tbl-sticky th:first-child,.tbl-sticky td:first-child{position:sticky;left:0;z-index:2;box-shadow:2px 0 4px rgba(0,0,0,0.06);}
.tbl-sticky th:first-child{background:var(--bg-th);z-index:3;}
.tbl-sticky .subheader-row th:first-child{background:var(--bg-th2);z-index:3;}
.tbl-sticky tr:nth-child(even) td:first-child{background:var(--bg-row-alt);}
.tbl-sticky tr:hover td:first-child{background:var(--bg-row-hover)!important;}

/* number cells */
td.num-cell{text-align:right;font-variant-numeric:tabular-nums;}
/* code cells */
td.code-cell{font-family:'JetBrains Mono',monospace;font-size:10.5px;color:var(--text-sub);white-space:nowrap;letter-spacing:0;}
/* product name cells - truncate */
td.name-cell{max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
td.wide-name-cell{max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}

/* row types */
tr.total-row td{background:var(--bg-total)!important;font-weight:600;border-top:1.5px solid var(--border);}
tr.subtotal-row td{background:var(--bg-subtotal)!important;font-weight:500;font-style:italic;}
tr.summary-row td{background:#DDE5F5!important;font-weight:600;border-top:1.5px solid var(--border);color:var(--navy);}

/* value colors */
.val-positive{color:var(--positive);}
.val-negative{color:var(--negative);}

/* heat map cells */
.heat-pos-1 td,.heat-pos-1{background:var(--heat-pos-1)!important;}
.heat-pos-2 td,.heat-pos-2{background:var(--heat-pos-2)!important;}
.heat-pos-3 td,.heat-pos-3{background:var(--heat-pos-3)!important;}
.heat-pos-4 td,.heat-pos-4{background:var(--heat-pos-4)!important;}
.heat-pos-5 td,.heat-pos-5{background:var(--heat-pos-5)!important;color:var(--positive);}
.heat-neg-1 td,.heat-neg-1{background:var(--heat-neg-1)!important;}
.heat-neg-2 td,.heat-neg-2{background:var(--heat-neg-2)!important;}
.heat-neg-3 td,.heat-neg-3{background:var(--heat-neg-3)!important;}
.heat-neg-4 td,.heat-neg-4{background:var(--heat-neg-4)!important;}
.heat-neg-5 td,.heat-neg-5{background:var(--heat-neg-5)!important;color:var(--negative);}

/* ── Tabs ── */
.tabs-container{}
.tab-buttons{display:flex;gap:0;margin-bottom:12px;border-bottom:2px solid var(--border);}
.tab-btn{background:none;border:none;border-bottom:2px solid transparent;margin-bottom:-2px;padding:7px 18px;font-size:12px;color:var(--text-sub);cursor:pointer;font-family:inherit;transition:color 0.12s;}
.tab-btn:hover{color:var(--navy);}
.tab-btn.active{color:var(--navy);border-bottom-color:var(--gold);font-weight:600;}
.tab-content{display:none;}
.tab-content.active{display:block;}

/* ── Overview ── */
.overview-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:14px;}
.stat-card{background:var(--bg-card);border:1px solid var(--border);border-radius:3px;padding:14px 15px;border-top:3px solid var(--border);}
.stat-card.stat-primary{border-top-color:var(--gold);}
.stat-card.stat-ok{border-top-color:var(--positive);}
.stat-card.stat-alert{border-top-color:var(--negative);}
.stat-label{font-size:10px;color:var(--text-muted);margin-bottom:6px;text-transform:uppercase;letter-spacing:0.5px;}
.stat-value{font-family:'Noto Serif SC',serif;font-size:21px;font-weight:700;color:var(--navy);}
.stat-sub{font-size:11px;color:var(--text-muted);margin-top:4px;}
.stat-positive{color:var(--positive);}
.stat-negative{color:var(--negative);}
.bar-chart{display:flex;flex-direction:column;gap:4px;margin-top:4px;}
.bar-row{display:flex;align-items:center;gap:7px;}
.bar-label{width:74px;font-size:10px;color:var(--text-sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:right;flex-shrink:0;}
.bar-track{flex:1;height:5px;background:var(--border-lt);border-radius:2px;overflow:hidden;}
.bar-fill{height:100%;border-radius:2px;}
.bar-value{width:36px;font-size:10px;color:var(--text-sub);text-align:right;font-variant-numeric:tabular-nums;flex-shrink:0;}
.text-card{margin-bottom:8px;padding:9px 11px;background:var(--bg);border-radius:2px;border:1px solid var(--border-lt);}
.text-card-label{font-size:9.5px;color:var(--gold);font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;}
.text-card-content{font-size:11.5px;color:var(--text-sub);line-height:1.65;}
.text-cards-inline{display:flex;flex-direction:column;gap:5px;max-height:310px;overflow-y:auto;}
.text-cards-inline::-webkit-scrollbar{width:3px;}
.text-cards-inline::-webkit-scrollbar-thumb{background:var(--border);}

/* ── Series ops ── */
.series-nav{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px;}
.series-nav-btn{padding:4px 10px;font-size:11px;background:var(--bg-card);border:1px solid var(--border);border-radius:2px;cursor:pointer;color:var(--text-sub);transition:all 0.12s;font-family:inherit;}
.series-nav-btn:hover,.series-nav-btn.active{background:var(--gold-light);border-color:var(--gold);color:var(--navy);font-weight:500;}
.series-block{margin-bottom:28px;}
.series-block-header{display:flex;align-items:baseline;gap:10px;margin-bottom:6px;padding-bottom:5px;border-bottom:1px solid var(--border-lt);}
.series-block-title{font-family:'Noto Serif SC',serif;font-size:14px;font-weight:600;color:var(--navy);}
.series-block-stats{font-size:10.5px;color:var(--text-muted);}

/* ── Toast ── */
.upload-toast{position:fixed;bottom:20px;right:20px;background:var(--navy);color:#fff;border-radius:3px;border-left:4px solid var(--gold);padding:10px 14px;font-size:12px;box-shadow:0 4px 16px rgba(0,0,0,0.18);z-index:9999;max-width:340px;animation:toastIn 0.18s ease;}
.upload-toast.success{border-left-color:var(--positive);}
.upload-toast.error{border-left-color:var(--negative);}
@keyframes toastIn{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:translateY(0);}}

/* ── Footer ── */
footer{text-align:center;font-size:10.5px;color:var(--text-muted);padding:16px;border-top:1px solid var(--border);margin-top:30px;}

/* ── Empty ── */
.empty-state{color:var(--text-muted);text-align:center;padding:36px 20px;font-size:12px;border:1px dashed var(--border);border-radius:3px;background:var(--bg-card);}

/* ── Print ── */
@media print{
  .top-header,.sidebar{display:none;}
  .main-content{margin:0;padding:8px;}
  .tab-content{display:block!important;}
  .tab-content::before{content:attr(data-tab-label);font-weight:bold;display:block;margin:8px 0 3px;}
  .section{break-inside:avoid-page;margin-bottom:20px;}
  .table-wrapper{overflow:visible;border:1px solid #999;}
  th{background:#1A1A1A!important;color:#fff!important;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  .total-row td{background:#DDDDD0!important;-webkit-print-color-adjust:exact;}
}
