function normalizeSheetName(name){let r='';for(let i=0;i<name.length;i++){const c=name[i];r+=KANGXI_MAP[c]||c;}return r;}
function findSheet(sheets,name){if(sheets[name])return sheets[name];const n=normalizeSheetName(name);for(const k of Object.keys(sheets)){if(normalizeSheetName(k)===n)return sheets[k];}return null;}
function findSheetKey(sheets,name){if(sheets[name]!==undefined)return name;const n=normalizeSheetName(name);for(const k of Object.keys(sheets)){if(normalizeSheetName(k)===n)return k;}return null;}
function setHasNorm(s,name){if(s.has(name))return true;const n=normalizeSheetName(name);for(const item of s){if(normalizeSheetName(item)===n)return true;}return false;}

/* ====== Utility ====== */
function isNumeric(v){if(v==null)return false;if(typeof v==='number')return isFinite(v);if(typeof v==='string'){const n=parseFloat(v);return !isNaN(n)&&isFinite(n);}return false;}
function toFloat(v){if(v==null)return null;if(typeof v==='number')return isFinite(v)?v:null;if(typeof v==='string'){if(v===''||v==='nan'||v==='inf'||v==='-inf')return null;const n=parseFloat(v);return isFinite(n)?n:null;}return null;}
function escHtml(s){if(s==null)return '';return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

/* ====== Column Filter / Reorder ====== */
function filterColumnsForDisplay(data, sheetName) {
  if (!data || data.length === 0) return data;
  const headers = data[0];
  const normSheet = normalizeSheetName(sheetName);

  // Check COLUMN_DISPLAY whitelist
  let wantCols = null;
  for (const [sheet, cols] of Object.entries(COLUMN_DISPLAY)) {
    if (normalizeSheetName(sheet) === normSheet) { wantCols = cols; break; }
  }

  if (wantCols) {
    // Build header→index map (trim whitespace)
    const hMap = {};
    headers.forEach((h, i) => { if (h != null) hMap[String(h).trim()] = i; });
    // Map to indices, skipping any column not found
    const indices = wantCols.map(c => hMap[c]).filter(i => i !== undefined);
    if (indices.length === 0) return data;
    return data.map(row => indices.map(i => (i < row.length ? row[i] : null)));
  }

  // No whitelist: filter out ALWAYS_HIDE columns
  const keepIdx = [];
  headers.forEach((h, i) => {
    const ht = h != null ? String(h).trim() : '';
    if (!ALWAYS_HIDE_COLS.has(ht)) keepIdx.push(i);
  });
  if (keepIdx.length === headers.length) return data;
  return data.map(row => keepIdx.map(i => (i < row.length ? row[i] : null)));
}

/* ====== Column Type Detection ====== */
function detectColumnTypes(data, sheetName) {
  if (!data || !data[0]) return {};
  const headers = data[0];
  const colTypes = {};
  for (let ci = 0; ci < headers.length; ci++) {
    const h = String(headers[ci] || '');
    // Text cols
    if (TEXT_COL_NAMES.has(h.trim())) { colTypes[ci] = 'text'; continue; }
    // PCT_RAW
    if (setHasNorm(PCT_RAW_SHEETS, sheetName)) {
      if (/年化|收益率|波动率|占比/.test(h)) { colTypes[ci] = 'percent_raw'; continue; }
    }
    // PCT_DECIMAL
    if (setHasNorm(PCT_DECIMAL_SHEETS, sheetName)) {
      if (/年化|收益率|波动率|占比/.test(h)) { colTypes[ci] = 'percent'; continue; }
    }
    if (/bp/i.test(h)) { colTypes[ci] = 'bps'; continue; }
    // Auto-detect
    const isPctHdr = /年化|收益率|波动率|占比|比例/.test(h);
    const numVals = [];
    for (let ri = 1; ri < Math.min(data.length, 20); ri++) {
      if (ci < data[ri].length) {
        const v = toFloat(data[ri][ci]);
        if (v != null && v !== 0) numVals.push(Math.abs(v));
      }
    }
    if (isPctHdr && numVals.length > 0) {
      const avg = numVals.reduce((a,b)=>a+b,0)/numVals.length;
      colTypes[ci] = avg > 0.5 ? 'percent_raw' : 'percent';
    } else if (numVals.length >= 2) {
      const avg = numVals.reduce((a,b)=>a+b,0)/numVals.length;
      const mx = Math.max(...numVals);
      if (avg > 0 && avg < 0.5 && mx < 1.5) colTypes[ci] = 'percent';
    }
  }
  return colTypes;
}

/* ====== Cell Value Formatting ====== */
function formatCellValue(val, colType, useParens) {
  if (val == null) return '';
  // Text column: always return as string
  if (colType === 'text') {
    const s = String(val).trim();
    return s === 'nan' || s === '' ? '' : escHtml(s);
  }
  if (typeof val === 'string') {
    if (val === 'nan' || val === 'inf' || val === '-inf') return '';
    const n = parseFloat(val);
    if (isFinite(n)) val = n; else return escHtml(val);
  }
  if (typeof val !== 'number' || !isFinite(val)) return '';
  if (colType === 'percent') return (val * 100).toFixed(2) + '%';
  if (colType === 'percent_raw') return val.toFixed(2) + '%';
  if (colType === 'bps') return val.toFixed(2);
  if (useParens) {
    if (Math.abs(val) < 0.05) return '-';
    if (Math.abs(val) < 1 && Math.abs(val) >= 0.05)
      return val < 0 ? '(' + Math.abs(val).toFixed(1) + ')' : val.toFixed(1);
    const r = Math.round(val);
    if (r === 0) return '-';
    if (r < 0) return '(' + Math.abs(r).toLocaleString() + ')';
    return r.toLocaleString();
  }
  if (Number.isInteger(val) || (val === Math.floor(val) && Math.abs(val) < 10000)) return String(Math.floor(val));
  if (Math.abs(val) < 0.0001 && val !== 0) return val.toFixed(6);
  if (Math.abs(val) < 0.01 && val !== 0) return val.toFixed(4);
  if (Math.abs(val) < 100) return val.toFixed(2);
  if (Math.abs(val) < 100000) return val.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
  return Math.round(val).toLocaleString();
}

/* ====== Cell CSS Classes ====== */
function getCellClass(val, colType, header) {
  const fval = toFloat(val);
  if (fval == null || colType === 'text') return '';
  const h = String(header).toLowerCase();
  const cls = [];
  const isChange = /变化|较上周|较上月|较上年|bp/.test(h);
  const isReturn = /年化|收益率/.test(h);
  if (isChange) { if (fval > 0) cls.push('val-positive'); else if (fval < 0) cls.push('val-negative'); }
  if (isReturn && colType === 'percent' && fval < 0) cls.push('val-negative');
  if (isChange && fval !== 0) {
    let intensity;
    if (colType === 'percent') intensity = Math.min(Math.abs(fval) * 20, 1);
    else if (colType === 'percent_raw') intensity = Math.min(Math.abs(fval) / 5, 1);
    else if (/bp/.test(h)) intensity = Math.min(Math.abs(fval) / 50, 1);
    else intensity = Math.min(Math.abs(fval) / 20, 1);
    const level = Math.min(Math.floor(intensity * 5) + 1, 5);
    cls.push(fval > 0 ? 'heat-pos-' + level : 'heat-neg-' + level);
  }
  return cls.join(' ');
}

/* ====== Table HTML Generation ====== */
function generateTableHTML(sheetName, sheetData) {
  if (!sheetData || !sheetData.data || sheetData.data.length === 0) return '<div class="empty-state">暂无数据</div>';

  // Apply column filter/reorder
  const data = filterColumnsForDisplay(sheetData.data, sheetName);
  const colTypes = detectColumnTypes(data, sheetName);
  const useParens = setHasNorm(SCALE_INT_SHEETS, sheetName);
