  const isWide = numCols > 8;

  let html = '';
  for (let ri = 0; ri < data.length; ri++) {
    const row = data[ri];
    const isHeader = ri === 0;
    let isSubheader = false;
    if (ri === 1 || ri === 2) {
      const vals = row.filter(v => v != null);
      const numC = vals.filter(v => isNumeric(v)).length;
      const firstVal = row[0] != null ? String(row[0]).trim() : '';
      // Don't treat rows starting with product codes as subheaders
      const looksLikeCode = /^\d[A-Za-z0-9]{5,}/.test(firstVal) || /^\d{8}$/.test(firstVal);
      if (!looksLikeCode && vals.length > 0 && (vals.length - numC) > numC && (vals.length - numC) >= 2) isSubheader = true;
    }

    let cells = '';
    for (let ci = 0; ci < Math.min(row.length, numCols); ci++) {
      const val = row[ci];
      const tag = (isHeader || isSubheader) ? 'th' : 'td';
      const colH = data[0][ci] != null ? String(data[0][ci]).trim() : '';
      const colType = colTypes[ci] || null;
      let display;
      if (isHeader || isSubheader) {
        display = val != null ? escHtml(String(val)) : '';
      } else {
        display = formatCellValue(val, colType, useParens);
      }
      let cls = [];
      if (!isHeader && !isSubheader) {
        const cc = getCellClass(val, colType, colH); if (cc) cls.push(cc);
        if (colType === 'text') cls.push('code-cell');
        else if (toFloat(val) != null) cls.push('num-cell');
        if (NAME_COL_NAMES.has(colH)) cls.push('name-cell');
      }
      const clsStr = cls.length ? ' class="' + cls.join(' ') + '"' : '';
      // Add title tooltip for truncated name cells
      const titleAttr = (!isHeader && !isSubheader && NAME_COL_NAMES.has(colH) && val != null)
        ? ' title="' + escHtml(String(val)) + '"' : '';
      cells += '<' + tag + clsStr + titleAttr + '>' + display + '</' + tag + '>';
    }

    let rowCls = '';
    if (isHeader) rowCls = 'header-row';
    else if (isSubheader) rowCls = 'subheader-row';
    else {
      const f = String(row[0] || '').trim();
      const s = row.length > 1 ? String(row[1] || '').trim() : '';
      if (['合计','总计','总合计','汇总','总规模'].includes(f) || ['合计','总计','汇总'].includes(s))
        rowCls = 'total-row';
      else if (s.includes('合计') || f.includes('合计')) rowCls = 'subtotal-row';
      else if (row.slice(0,3).some(v => String(v||'').includes('合计'))) rowCls = 'total-row';
    }
    const rcAttr = rowCls ? ' class="' + rowCls + '"' : '';
    html += '<tr' + rcAttr + '>' + cells + '</tr>';
  }
  const tblCls = isWide ? ' class="tbl-sticky"' : '';
  return '<div class="table-wrapper"><table' + tblCls + '>' + html + '</table></div>';
}

/* ====== Preprocessing ====== */
function preprocessSheets(sheets) {
  // 1. 分渠道余额 subtotals
  const ch = findSheet(sheets, '1、分渠道余额');
  if (ch && ch.data && ch.data.length > 3) {
    const d = ch.data;
    const newData = d.slice(0, 3);
    const groups = {};
    let curGroup = null;
    for (let ri = 3; ri < d.length; ri++) {
      const row = d[ri];
      if (row[0] != null) curGroup = String(row[0]);
      if (curGroup) { if (!groups[curGroup]) groups[curGroup] = []; groups[curGroup].push(row); }
    }
    const grandTotal = [0, 0];
    for (const gn of ['中低波稳健产品','中高波市值产品','外币产品']) {
      const rows = groups[gn] || [];
      const sub = [0, 0];
      for (const row of rows) {
        const v1 = toFloat(row[2]); const v2 = toFloat(row[3]);
        if (v1) sub[0] += v1; if (v2) sub[1] += v2;
        newData.push(row);
      }
      newData.push([null, gn + '合计', Math.round(sub[0]), Math.round(sub[1])]);
      grandTotal[0] += sub[0]; grandTotal[1] += sub[1];
    }
    if (newData[0].length === 4) {
      newData[0] = [null, null, '保有规模', null, null];
      newData[1] = [null, '渠道-行内外', '行内', '行外', '合计'];
      newData[2] = ['总分类', '母分类', null, null, null];
    }
    for (let ri = 3; ri < newData.length; ri++) {
      const row = newData[ri];
      if (row.length === 4) row.push(Math.round((toFloat(row[2])||0) + (toFloat(row[3])||0)));
    }
    newData.push([null, '总计', Math.round(grandTotal[0]), Math.round(grandTotal[1]), Math.round(grandTotal[0]+grandTotal[1])]);
    ch.data = newData; ch.col_count = 5;
  }
  // 2. 产品规模 合计
  const ps = findSheet(sheets, '2、产品规模');
  if (ps && ps.data && ps.data.length > 1) {
    const d = ps.data;
    const hasTotal = d.slice(1).some(r => { const a=String(r[0]||'').trim(),b=String(r[1]||'').trim(); return a==='合计'||a==='总计'||b==='合计'||b==='总计'; });
    if (!hasTotal) {
      const totals = new Array(d[0].length).fill(0);
      for (const row of d.slice(1)) { for (let ci=2;ci<row.length;ci++){const v=toFloat(row[ci]);if(v)totals[ci]+=v;} }
      const totalRow = ['','合计']; for (let ci=2;ci<d[0].length;ci++) totalRow.push(Math.round(totals[ci]));
      while (totalRow.length < d[0].length) totalRow.push(null);
      d.push(totalRow);
    }
  }
  // 3. 投资经理维度 合计
  const pm = findSheet(sheets, '投资经理维度产品规模和数量');
  if (pm && pm.data && pm.data.length > 1) {
    const d = pm.data;
    const hasTotal = d.slice(1).some(r => String(r[0]||'').trim()==='合计');
    if (!hasTotal) {
      const totals = new Array(d[0].length).fill(0);
      for (const row of d.slice(1)) { for (let ci=1;ci<row.length;ci++){const v=toFloat(row[ci]);if(v)totals[ci]+=v;} }
      const totalRow = ['合计']; for (let ci=1;ci<d[0].length;ci++) totalRow.push(Math.round(totals[ci]*10)/10);
      while (totalRow.length < d[0].length) totalRow.push(null);
      d.push(totalRow);
    }
  }
}

/* ====== Overview Stats ====== */
function computeOverviewStats(sheets) {
  const stats = {};
  const ps = findSheet(sheets, '2、产品规模');
  if (ps && ps.data) {
    let totalAum=0,totalCount=0,aumM=0,aumY=0;
    for (const row of ps.data.slice(1)) {
      const f=String(row[0]||'').trim(),s=String(row[1]||'').trim();
      if (['合计','总计'].includes(f)||['合计','总计'].includes(s)) continue;
      let v=toFloat(row[2]); if(v)totalAum+=v;
      v=toFloat(row[5]); if(v)totalCount+=v;
      v=toFloat(row[3]); if(v)aumM+=v;
      v=toFloat(row[4]); if(v)aumY+=v;
    }
    stats.totalAum=totalAum; stats.totalCount=totalCount; stats.aumM=aumM; stats.aumY=aumY;
  }
  const ts = findSheet(sheets, '总结文字');
  if (ts && ts.data) {
    for (const row of ts.data.slice(1)) {
      if (row.length>=2&&row[0]&&row[1]) {
        const k=String(row[0]),v=String(row[1]);
        if (k.includes('规模')) stats.guimoText=v;
        else if (k.includes('中收')) stats.zhongshouText=v;
        else if (k.includes('到期')) stats.daoqiText=v;
      }
    }
  }
  const bp=findSheet(sheets,'破净结果'); if(bp&&bp.data)stats.brokenCount=bp.data.slice(1).filter(r=>r.some(v=>v!=null)).length;
  const up=findSheet(sheets,'招商在售产品不达基准'); if(up&&up.data)stats.underperformCount=up.data.length-1;
  const hv=findSheet(sheets,'12.周净值高波动产品清单'); if(hv&&hv.data)stats.highVolCount=hv.data.length-1;
  return stats;
}

function generateOverviewHTML(stats, sheets) {
  const aum=stats.totalAum;
  const aumStr=aum>100?Math.round(aum).toLocaleString()+'亿':(aum?aum.toFixed(2)+'亿':'N/A');
  const countStr=stats.totalCount?Math.round(stats.totalCount)+'只':'N/A';
  const aumMStr=stats.aumM!=null?(stats.aumM>=0?'+':'')+Math.round(stats.aumM)+'亿':'N/A';
  const aumMCls=stats.aumM>0?'stat-positive':(stats.aumM<0?'stat-negative':'');
  const aumYStr=stats.aumY!=null?(stats.aumY>=0?'+':'')+Math.round(stats.aumY)+'亿':'N/A';
  const aumYCls=stats.aumY>0?'stat-positive':(stats.aumY<0?'stat-negative':'');
  const broken=stats.brokenCount||0;
  const brokenStr=broken>0?broken+'只':'无';
  const underperf=stats.underperformCount||0;
  const highVol=stats.highVolCount||0;
  let textCards='';
  for (const [key,label] of [['guimoText','规模概况'],['zhongshouText','中收概况'],['daoqiText','到期概况']]) {
    const text=stats[key]||'';
    if(text)textCards+='<div class="text-card"><div class="text-card-label">'+label+'</div><div class="text-card-content">'+escHtml(text).replace(/\n/g,'<br>')+'</div></div>';
  }
  let barItems='';
  const ps=findSheet(sheets,'2、产品规模');
  if(ps&&ps.data){
    let maxAum=0;
    for(const row of ps.data.slice(1)){const s=String(row[1]||'').trim();if(['合计','总计'].includes(s))continue;const v=toFloat(row[2]);if(v&&v>maxAum)maxAum=v;}
    for(const row of ps.data.slice(1)){
      const name=String(row[1]||'');if(['合计','总计'].includes(name.trim()))continue;
      const v=toFloat(row[2])||0,chg=toFloat(row[3])||0;
      if(v&&name){
        const pct=maxAum>0?(v/maxAum*100):0;
        const color=chg>0?'var(--positive)':(chg<0?'var(--negative)':'var(--gold)');
        barItems+='<div class="bar-row"><div class="bar-label" title="'+escHtml(name)+'">'+escHtml(name.slice(0,8))+'</div><div class="bar-track"><div class="bar-fill" style="width:'+pct.toFixed(1)+'%;background:'+color+'"></div></div><div class="bar-value">'+Math.round(v)+'</div></div>';
      }
    }
  }
  return '<div class="overview-grid">'+
    '<div class="stat-card stat-primary"><div class="stat-label">管理规模</div><div class="stat-value">'+aumStr+'</div>'+
    '<div class="stat-sub"><span class="'+aumMCls+'">较上月 '+aumMStr+'</span> <span class="'+aumYCls+'">较年初 '+aumYStr+'</span></div></div>'+
    '<div class="stat-card"><div class="stat-label">产品数量</div><div class="stat-value">'+countStr+'</div></div>'+
    '<div class="stat-card '+(broken>0?'stat-alert':'stat-ok')+'"><div class="stat-label">破净产品</div><div class="stat-value">'+brokenStr+'</div></div>'+
    '<div class="stat-card '+(underperf>3?'stat-alert':'')+'"><div class="stat-label">不达基准</div><div class="stat-value">'+underperf+'只</div></div>'+
    '<div class="stat-card '+(highVol>20?'stat-alert':'')+'"><div class="stat-label">高波动产品</div><div class="stat-value">'+highVol+'只</div></div>'+
    '</div>'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;">'+
    '<div class="stat-card" style="padding:14px 16px"><div class="stat-label" style="margin-bottom:8px">各系列规模分布 (亿)</div><div class="bar-chart">'+barItems+'</div></div>'+
    '<div class="stat-card" style="padding:14px 16px"><div class="stat-label" style="margin-bottom:5px">AI 摘要</div><div class="text-cards-inline">'+textCards+'</div></div>'+
    '</div>';
}

/* ====== Rebuild Dashboard ====== */
function rebuildDashboard(sheets) {
  for (const section of SECTION_CONFIG) {
    const el = document.getElementById(section.id);
    if (!el) continue;
    const header = el.querySelector('.section-header');
    const headerHTML = header ? header.outerHTML : '<h2 class="section-header">'+escHtml(section.title)+'</h2>';
    let contentHTML = '';
    if (section.type === 'overview') {
      const stats = computeOverviewStats(sheets);
      contentHTML = generateOverviewHTML(stats, sheets);
    } else if (section.type === 'tabs') {
      let tabBtns='', tabContents='', tabIdx=0;
      for (const sn of section.sheets) {
        const sd = findSheet(sheets, sn); if (!sd) continue;
        const short = sn.replace('系列产品业绩-','');
        const active = tabIdx===0?' active':'';
        const actualKey = findSheetKey(sheets, sn) || sn;
        tabBtns += '<button class="tab-btn'+active+'" onclick="switchTab(\''+section.id+'\','+tabIdx+')" data-tabgroup="'+section.id+'" data-tabidx="'+tabIdx+'">'+escHtml(short)+'</button>';
        tabContents += '<div class="tab-content'+active+'" data-tab="'+section.id+'-tab-'+tabIdx+'" data-tab-label="'+escHtml(short)+'">'+generateTableHTML(actualKey, sd)+'</div>';
        tabIdx++;
      }
      contentHTML = '<div class="tabs-container"><div class="tab-buttons">'+tabBtns+'</div>'+tabContents+'</div>';
    } else {
      for (const sn of section.sheets) {
        const sd = findSheet(sheets, sn); if (!sd) continue;
        const actualKey = findSheetKey(sheets, sn) || sn;
        contentHTML += '<h3 class="sheet-title">'+escHtml(actualKey)+'</h3>' + generateTableHTML(actualKey, sd);
      }
    }
    el.innerHTML = headerHTML + contentHTML;
  }
  initTableSort();
}

/* ====== Series Operations Section ====== */
const SERIES_FIXED_COLS  = ['产品代码','产品简称','净资产(亿)','形态','业绩基准','本期年化','累计年化','杠杆','组合久期','组合静态','运作天','剩余天','产品经理'];
const SERIES_EQUITY_COLS = ['产品代码','产品简称','净资产(亿)','形态','业绩基准','本期年化','累计年化','杠杆','权益仓位','组合久期','运作天','剩余天','产品经理'];
const SERIES_FX_COLS     = ['产品代码','产品简称','净资产(亿)','形态','业绩基准','本期年化','累计年化','杠杆','运作天','剩余天','产品经理'];
const EQUITY_MU = new Set(['逸动短持','灵动短持','兴动短持','含权定开/封闭','优先股短持','ESG联名','和瑞BOF','外币市值']);
const FX_ONLY_MU = new Set(['外币低波']);
const MU_ORDER  = ['悦动稳享短持','悦动稳/纯享','优先股短持','丰利/增盈','行外非标驱动型固收+','和瑞BOF','悦动短持/定开','逸动短持','灵动短持','兴动短持','含权定开/封闭','ESG联名','外币低波','外币市值'];
const SERIES_PCT_COLS = new Set(['本期年化','累计年化','业绩基准','权益仓位']);

function getSeriesCols(mu) {
  if (FX_ONLY_MU.has(mu)) return SERIES_FX_COLS;
  if (EQUITY_MU.has(mu)) return SERIES_EQUITY_COLS;
  return SERIES_FIXED_COLS;
}

function formatSeriesVal(val, colName) {
  if (val == null || val === '') return '';
  const s = String(val);
  if (s.toLowerCase() === 'nan' || s === '') return '';
  if (TEXT_COL_NAMES.has(colName)) return s; // product code as text
  if (SERIES_PCT_COLS.has(colName)) {
    const n = parseFloat(val);
    if (!isFinite(n)) return s;
    // Values stored as decimals (e.g. 0.025 → 2.50%)
    return n < 2 && n > -2 ? (n * 100).toFixed(2) + '%' : n.toFixed(2) + '%';
  }
  if (['净资产(亿)','杠杆','组合久期','组合静态'].includes(colName)) {
    const n = parseFloat(val); return isFinite(n) ? n.toFixed(2) : s;
  }
  if (['运作天','剩余天'].includes(colName)) {
    const n = parseFloat(val); return isFinite(n) ? Math.round(n).toString() : s;
  }
  // Date columns
  if (['起息日','到期日'].includes(colName)) {
    if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
    const n = parseInt(val);
    if (!isNaN(n) && n > 40000) { // Excel serial date
      const d = new Date(Date.UTC(1899,11,30) + n*86400000);
      return d.toISOString().slice(0,10);
    }
    return s;
  }
  return s;
}

function generateSeriesTableHTML(rows, cols) {
  if (!rows || rows.length === 0) return '<div class="empty-state">无数据</div>';
  let html = '<div class="table-wrapper"><table class="tbl-sticky"><tr class="header-row">';
  for (const c of cols) html += '<th>' + escHtml(c) + '</th>';
  html += '</tr>';
  // Data rows
  let totalAum = 0;
  const aumIdx = cols.indexOf('净资产(亿)');
  for (const row of rows) {
    html += '<tr>';
    for (const c of cols) {
      let val = row[c];
      const display = formatSeriesVal(val, c);
      let cls = '';
      if (TEXT_COL_NAMES.has(c)) cls = 'code-cell';
      else if (NAME_COL_NAMES.has(c)) cls = 'name-cell';
      else if (['净资产(亿)','运作天','剩余天'].includes(c)) cls = 'num-cell';
      else if (SERIES_PCT_COLS.has(c)) {
        const n = typeof val === 'number' ? val : parseFloat(val);
        cls = 'num-cell' + (isFinite(n) && n < 0 ? ' val-negative' : '');
      }
      const titleAttr = NAME_COL_NAMES.has(c) && val != null ? ' title="'+escHtml(String(val))+'"' : '';
      html += '<td' + (cls ? ' class="'+cls.trim()+'"' : '') + titleAttr + '>' + escHtml(display) + '</td>';
    }
    html += '</tr>';
    if (aumIdx >= 0) {
      const v = parseFloat(row['净资产(亿)']);
      if (isFinite(v)) totalAum += v;
    }
  }
  // Summary row
  html += '<tr class="total-row">';
  for (let ci = 0; ci < cols.length; ci++) {
    const c = cols[ci];
    if (ci === 0) { html += '<td class="code-cell">—</td>'; continue; }
    if (ci === 1) { html += '<td style="font-weight:600">合计</td>'; continue; }
    if (c === '净资产(亿)') { html += '<td class="num-cell" style="font-weight:600">' + totalAum.toFixed(2) + '</td>'; continue; }
    // Weighted avg for performance cols
    if (SERIES_PCT_COLS.has(c)) {
      // compute AUM-weighted average
      let wSum = 0, wTotal = 0;
      for (const row of rows) {
        const w = parseFloat(row['净资产(亿)']);
        const v = parseFloat(row[c]);
        if (isFinite(w) && isFinite(v)) { wSum += w * v; wTotal += w; }
      }
      const avg = wTotal > 0 ? wSum / wTotal : null;
      html += '<td class="num-cell">' + (avg != null ? (avg < 2 && avg > -2 ? (avg*100).toFixed(2)+'%' : avg.toFixed(2)+'%') : '') + '</td>';
      continue;
    }
    html += '<td></td>';
  }
  html += '</tr>';
  html += '</table></div>';
  return html;
}

function rebuildSeriesSection(rawData) {
  const content = document.getElementById('series-ops-content');
  if (!content) return;
  if (!rawData || rawData.length === 0) { content.innerHTML = '<div class="empty-state">数据为空</div>'; return; }

  const data = rawData.filter(r => String(r['主要展示'] || '').trim() === '是');
  const groups = {};
  for (const row of data) {
    const mu = String(row['母分类'] || '').trim();
    if (!mu) continue;
    if (!groups[mu]) groups[mu] = [];
    groups[mu].push(row);
  }

  const order = MU_ORDER.filter(m => groups[m]);
  for (const mu of Object.keys(groups)) { if (!order.includes(mu)) order.push(mu); }

  // Nav buttons
  let navHTML = '<div class="series-nav">';
  for (const mu of order) navHTML += '<button class="series-nav-btn" onclick="scrollToSeries(\''+escHtml(mu)+'\')">'+escHtml(mu)+'</button>';
  navHTML += '</div>';

  let tablesHTML = '';
  for (const mu of order) {
    const rows = groups[mu];
    rows.sort((a, b) => (parseFloat(b['净资产(亿)']) || 0) - (parseFloat(a['净资产(亿)']) || 0));
    const cols = getSeriesCols(mu);
    const totalAum = rows.reduce((s, r) => s + (parseFloat(r['净资产(亿)']) || 0), 0);
    const avgRet = (() => {
      let wSum=0, wT=0;
      for (const r of rows) { const w=parseFloat(r['净资产(亿)']), v=parseFloat(r['本期年化']); if(isFinite(w)&&isFinite(v)){wSum+=w*v;wT+=w;} }
      return wT > 0 ? (wSum/wT*100).toFixed(2)+'%' : '—';
    })();
    tablesHTML += '<div class="series-block" id="series-mu-'+encodeURIComponent(mu)+'">';
    tablesHTML += '<div class="series-block-header">';
    tablesHTML += '<span class="series-block-title">'+escHtml(mu)+'</span>';
    tablesHTML += '<span class="series-block-stats">'+rows.length+'只 · 规模 '+totalAum.toFixed(2)+'亿 · 本期加权年化 '+avgRet+'</span>';
    tablesHTML += '</div>';
    tablesHTML += generateSeriesTableHTML(rows, cols);
    tablesHTML += '</div>';
  }

  content.innerHTML = navHTML + tablesHTML;
  initTableSort();
}

function scrollToSeries(mu) {
  const el = document.getElementById('series-mu-' + encodeURIComponent(mu));
  if (el) { const hh = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--hdr-h')) || 52; const y = el.getBoundingClientRect().top + window.pageYOffset - hh - 10; window.scrollTo({ top: y, behavior: 'smooth' }); }
}

/* ====== File Upload Handlers ====== */
function showToast(msg, type) {
  document.querySelectorAll('.upload-toast').forEach(e => e.remove());
  const t = document.createElement('div');
  t.className = 'upload-toast ' + (type || '');
  t.innerHTML = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 5000);
}

async function handleFileUpload(e) {
  const file = e.target.files[0]; if (!file) return;
  if (!file.name.match(/\.(xlsx|xls)$/i)) { showToast('请上传 .xlsx 格式的Excel文件','error'); return; }
  showToast('正在解析 '+escHtml(file.name)+' ...','');
  try {
    const wb = XLSX.read(await file.arrayBuffer(), {type:'array'});
    const sheets = {};
    for (const name of wb.SheetNames) {
      const ws = wb.Sheets[name];
      const jsonData = XLSX.utils.sheet_to_json(ws, {header:1, defval:null, raw:true});
      sheets[name] = {data:jsonData, col_count:jsonData[0]?jsonData[0].length:0, merged_cells:(ws['!merges']||[]).map(m=>XLSX.utils.encode_range(m))};
    }
    preprocessSheets(sheets);
    rebuildDashboard(sheets);
    const dm = file.name.match(/(\d{8})/);
    if (dm) {
      const d=dm[1], ds=d.slice(0,4)+'-'+d.slice(4,6)+'-'+d.slice(6,8);
      document.querySelectorAll('.header-date').forEach(el=>el.textContent='数据截止 '+ds);
      document.querySelectorAll('footer').forEach(el=>el.innerHTML='兴银理财多资产投资部 | 数据截止 '+ds+' | 仪表板更新于 '+new Date().toLocaleString('zh-CN'));
    }
    showToast('数据导入成功！已加载 '+wb.SheetNames.length+' 张工作表','success');
  } catch(err) { console.error(err); showToast('解析失败: '+escHtml(err.message),'error'); }
  e.target.value = '';
}

async function handleOverviewUpload(e) {
  const file = e.target.files[0]; if (!file) return;
  if (!file.name.match(/\.(xlsx|xls)$/i)) { showToast('请上传 .xlsx 格式的Excel文件','error'); return; }
  showToast('正在解析运作概览文件 '+escHtml(file.name)+' ...','');
  try {
    const wb = XLSX.read(await file.arrayBuffer(), {type:'array', cellDates:false});
    const ws = wb.Sheets[wb.SheetNames[0]];
    const rawArr = XLSX.utils.sheet_to_json(ws, {header:1, defval:null, raw:true});
    if (rawArr.length < 2) { showToast('文件数据为空','error'); return; }
    const headers = rawArr[0].map(h => h != null ? String(h).trim() : '');
    const rows = rawArr.slice(1).map(arr => {
      const obj = {};
      headers.forEach((h, j) => { obj[h] = arr[j]; });
      return obj;
    });
    rebuildSeriesSection(rows);
    const dm = file.name.match(/(\d{8})/);
    if (dm) { const d=dm[1], ds=d.slice(0,4)+'-'+d.slice(4,6)+'-'+d.slice(6,8); document.querySelectorAll('.header-date').forEach(el=>el.textContent='数据截止 '+ds); }
    showToast('运作概览导入成功！共 '+rows.length+' 行数据','success');
  } catch(err) { console.error(err); showToast('解析失败: '+escHtml(err.message),'error'); }
  e.target.value = '';
}

/* ====== PDF Export ====== */
function exportPDF() {
  document.querySelectorAll('.tab-content').forEach(tc => {
    if (!tc.getAttribute('data-tab-label')) {
      const tabGroup = tc.getAttribute('data-tab');
      if (tabGroup) {
        const idx = tabGroup.split('-tab-')[1];
        const btn = document.querySelector('[data-tabgroup="'+tabGroup.split('-tab-')[0]+'"][data-tabidx="'+idx+'"]');
        if (btn) tc.setAttribute('data-tab-label', btn.textContent);
      }
    }
  });
  window.print();
}

/* ====== UI Interactions ====== */
function switchTab(groupId, tabIdx) {
  document.querySelectorAll('[data-tabgroup="'+groupId+'"]').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('[data-tab^="'+groupId+'-tab-"]').forEach(c => c.classList.remove('active'));
  document.querySelector('[data-tabgroup="'+groupId+'"][data-tabidx="'+tabIdx+'"]').classList.add('active');
  document.querySelector('[data-tab="'+groupId+'-tab-'+tabIdx+'"]').classList.add('active');
}

function initNavHighlight() {
  const sections = document.querySelectorAll('.section');
  const navItems = document.querySelectorAll('.nav-item');
  const obs = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const id = entry.target.id;
        navItems.forEach(item => item.classList.toggle('active', item.getAttribute('href')==='#'+id));
      }
    });
  }, {threshold:0.1, rootMargin:'-80px 0px -50% 0px'});
  sections.forEach(s => obs.observe(s));
  navItems.forEach(item => {
    item.addEventListener('click', e => {
      e.preventDefault();
      const targetId = item.getAttribute('href').substring(1);
      const target = document.getElementById(targetId);
      if (target) {
        const hh = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--hdr-h')) || 52;
        window.scrollTo({top: target.getBoundingClientRect().top + window.pageYOffset - hh - 16, behavior:'smooth'});
        history.pushState(null, null, '#'+targetId);
      }
    });
  });
}

function initSearch() {
  const input = document.getElementById('global-search'); if (!input) return;
  input.addEventListener('input', e => {
    const q = e.target.value.toLowerCase().trim();
    document.querySelectorAll('table').forEach(table => {
      table.querySelectorAll('tr:not(.header-row):not(.subheader-row)').forEach(row => {
        row.style.display = (!q || row.textContent.toLowerCase().includes(q)) ? '' : 'none';
      });
    });
  });
}

function initTableSort() {
  document.querySelectorAll('th').forEach(th => {
    th.style.cursor = 'pointer';
    th.addEventListener('click', () => {
      const table = th.closest('table');
      const idx = Array.from(th.parentNode.children).indexOf(th);
      const tbody = table.querySelector('tbody') || table;
      const rows = Array.from(tbody.querySelectorAll('tr')).filter(r =>
        !r.classList.contains('header-row') && !r.classList.contains('subheader-row') &&
        !r.classList.contains('total-row') && !r.classList.contains('subtotal-row') &&
        !r.classList.contains('summary-row'));
      const isAsc = th.getAttribute('data-sort') !== 'asc';
      th.setAttribute('data-sort', isAsc ? 'asc' : 'desc');
      rows.sort((a, b) => {
        const aV = a.children[idx]?.textContent?.trim()?.replace(/[()]/g,'') || '';
        const bV = b.children[idx]?.textContent?.trim()?.replace(/[()]/g,'') || '';
        const aN = parseFloat(aV.replace(/[,%亿万只]/g,''));
        const bN = parseFloat(bV.replace(/[,%亿万只]/g,''));
        if (!isNaN(aN) && !isNaN(bN)) return isAsc ? aN-bN : bN-aN;
        return isAsc ? aV.localeCompare(bV,'zh') : bV.localeCompare(aV,'zh');
      });
      rows.forEach(r => tbody.appendChild(r));
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  initNavHighlight();
  initSearch();
  initTableSort();
  const u1 = document.getElementById('file-upload');
  if (u1) u1.addEventListener('change', handleFileUpload);
  const u2 = document.getElementById('overview-upload');
  if (u2) u2.addEventListener('change', handleOverviewUpload);
});
